class InventoryManager {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
        console.log(`Picked up a ${item}.`);
    }

    removeItem(item) {
        const index = this.items.indexOf(item);
        if (index > -1) {
            this.items.splice(index, 1);
            console.log(`Used/Removed a ${item}.`);
            return true;
        }
        console.log(`${item} not found in inventory.`);
        return false;
    }

    getInventorySummary() {
        return `Inventory: ${this.items.join(', ') || 'empty'}`;
    }
}

class PlayerProfile {
    constructor(username) {
        this.username = username;
        this.level = 1;
        this.experience = 0;
        this.inventoryManager = new InventoryManager(); // Composition
    }

    gainExperience(amount) {
        this.experience += amount;
        if (this.experience >= this.level * 100) {
            this.levelUp();
        }
    }

    levelUp() {
        this.level++;
        this.experience = 0;
        console.log(`${this.username} leveled up to Level ${this.level}!`);
    }

    getProfileSummary() {
        return `${this.username} (Level ${this.level}, Exp: ${this.experience})`;
    }

    // Delegate inventory actions to the InventoryManager instance
    addItemToInventory(item) {
        this.inventoryManager.addItem(item);
    }

    getInventoryList() {
        return `${this.username}'s ${this.inventoryManager.getInventorySummary()}`;
    }
}

// Example Usage
const player1 = new PlayerProfile("HeroicCoder");
player1.gainExperience(50);
player1.addItemToInventory("Healing Potion");
player1.gainExperience(60); // Should level up
player1.addItemToInventory("Magic Sword");

console.log(player1.getProfileSummary());
console.log(player1.getInventoryList());
player1.inventoryManager.removeItem("Healing Potion");
console.log(player1.getInventoryList());

